    def copy_binary_file(source_path, destination_path):
        with open(source_path, "rb") as source_file:
            with open(destination_path, "wb") as destination_file:
                while True:
                    block = source_file.read(64 * 1024)

                    if block == b"":
                        break

                    destination_file.write(block)

