            # access unless the code stores a result itself.
            # Getters should usually avoid surprising expensive work or side
            # effects because access looks like ordinary attribute reading.
            # Internal storage commonly uses a different name such as _celsius to
            # avoid recursively calling the property itself.
        # COMPLEXITY:
            # Descriptor lookup adds small overhead, but total cost is determined
            # by the getter, setter, or deleter code.

    class PartTwoTemperature:
        def __init__(self, celsius):
            self.celsius = celsius

        @property
        def celsius(self):
            """Temperature measured in degrees Celsius."""
            return self._celsius

        @celsius.setter
        def celsius(self, new_value):
            if not isinstance(new_value, (int, float)):
                raise TypeError("Temperature must be numeric.")

            if new_value < -273.15:
                raise ValueError("Temperature cannot be below absolute zero.")

            self._celsius = float(new_value)

        @property
        def fahrenheit(self):
            return (self._celsius * 9 / 5) + 32

