            # or already sorted list.
            # The original input is not modified by sorted().
        # DICTIONARY INPUT:
            # sorted(dictionary) sorts dictionary keys.
            # Use dictionary.items() and a key function to sort by values.
        # KEY PARAMETER:
            # key must be None or a one-argument callable.
            # It is called exactly once per input item during a normal sort.
            # Python stores computed keys temporarily and compares those keys.
            # The returned list still contains the original items.
        # REVERSE PARAMETER:
            # reverse=True requests descending order.
            # It preserves sort stability rather than simply destroying tie order.
        # STABILITY:
            # Python sorting is stable: equal keys preserve original relative order.
            # Stability supports sorting by multiple fields in multiple passes.
        # ALGORITHM:
            # Python uses an adaptive, stable sorting system based on Timsort.
            # It discovers naturally ordered runs and can be very fast on data that
            # is already sorted or partially sorted.
            # Modern CPython uses a Powersort-based merge strategy within this
            # Timsort family. This is an implementation detail; portable programs
            # should rely on documented stability, not internal merge policy.
        # COMPARISON DETAILS:
            # Sorting primarily relies on less-than comparisons.
            # Badly behaved comparison methods, non-transitive orderings, NaN, or
            # mutation during comparison can produce surprising results or errors.
            # A key function is often the cleanest way to establish a total order.
        # SORTED VS LIST.SORT:
            # sorted(iterable) accepts any iterable and returns a new list.
            # list.sort() mutates an existing list and returns None.
        # EDGE CASES:
            # Sorting an infinite iterable never completes.
            # A key function exception stops the sort and propagates.
            # Sorting by locale-specific human language rules requires explicit
            # locale-aware transformation rather than default Unicode ordering.
        # TIME COMPLEXITY:
            # Best case on suitably ordered data: O(n).
            # Average and worst case: O(n log n).
            # A key function adds O(n) calls plus the cost of each call.
        # SPACE COMPLEXITY:
            # The returned list requires O(n) space.
            # Temporary key storage and merge buffers can also require O(n)
            # auxiliary space in the worst case.

    unsorted_numbers = [4, 1, 3, 2]
    sorted_numbers_example = sorted(unsorted_numbers)
    sorted_original_unchanged_example = unsorted_numbers
    sorted_descending_example = sorted(unsorted_numbers, reverse=True)
    sorted_string_example = sorted("Python")
    sorted_set_example = sorted({4, 1, 3, 2})

    sort_people = [
        {"name": "Mia", "age": 22},
        {"name": "Ana", "age": 20},
        {"name": "Luis", "age": 22}
    ]
    sorted_people_by_age_example = sorted(
        sort_people,
        key=lambda person: person["age"]
    )
    sorted_people_by_age_and_name_example = sorted(
        sort_people,
        key=lambda person: (person["age"], person["name"])
    )

    score_mapping = {"Ana": 95, "Luis": 88, "Mia": 91}
    sorted_mapping_keys_example = sorted(score_mapping)
    sorted_mapping_by_value_example = sorted(
        score_mapping.items(),
        key=lambda item: item[1],
        reverse=True
    )

    # staticmethod(function)
        # PURPOSE:
            # Wraps a function stored on a class so retrieving it through the class
            # or an instance does not automatically supply self or cls.
        # DESCRIPTOR BEHAVIOR:
            # An ordinary function stored on a class becomes a bound method when
            # accessed through an instance.
            # staticmethod prevents that binding and returns the underlying
            # function without an automatic first argument.
        # COMMON DECORATOR STYLE:
            # @staticmethod
            # def method_name(...):
        # WHEN TO USE:
            # The operation is conceptually related to the class but does not need
            # instance state or class state.
            # It can also signal organizational intent to readers.
        # ALTERNATIVE:
            # A module-level function may be simpler when the behavior does not
            # need to live in the class's public namespace.
        # EDGE CASES:
            # A static method can still access global names and explicitly passed
            # objects; it is not isolated from state.
            # It does not receive the subclass automatically, so classmethod is
            # usually better for alternate constructors or polymorphic class logic.
            # Zero-argument super() is generally not meaningful in a static method
            # because no self or cls argument is available.
        # RETURN VALUE:
            # staticmethod(function) creates a staticmethod descriptor when called
            # directly. Decorator use stores that descriptor in the class body.
        # COMPLEXITY:
            # Descriptor access is effectively O(1); called-function cost depends
            # on the function body.

    class PartTwoMathTools:
        @staticmethod
        def is_even(number):
            return number % 2 == 0

        @staticmethod
        def clamp(number, minimum, maximum):
            return max(minimum, min(number, maximum))

    staticmethod_class_example = PartTwoMathTools.is_even(8)
    math_tools_instance = PartTwoMathTools()
    staticmethod_instance_example = math_tools_instance.clamp(15, 0, 10)

    # str(object="")
    # str(bytes_or_buffer, encoding="utf-8", errors="strict")
        # PURPOSE:
            # Creates an immutable Unicode string or decodes bytes-like data.
        # NO-ARGUMENT FORM:
            # str() returns the empty string "".
        # OBJECT FORM:
            # str(object) calls object.__str__() when available.
            # If no specialized __str__ exists, Python generally falls back to a
            # representation based on __repr__().
        # DECODING FORM:
            # When encoding is supplied, the first argument must be bytes-like.
            # This form decodes bytes into Unicode text.
            # errors controls malformed byte handling.
        # IMPORTANT BYTES EDGE CASE:
            # str(b"hello") does NOT decode the bytes. It returns text resembling
            # "b'hello'".
            # Use b"hello".decode("utf-8") or str(b"hello", "utf-8") to decode.
        # IMMUTABILITY:
            # String contents cannot be changed in place.
            # Operations such as replace(), upper(), and concatenation create new
            # strings.
        # UNICODE:
            # Python str stores Unicode text, not a chosen external byte encoding.
            # Encoding turns str into bytes; decoding turns bytes into str.
        # EDGE CASES / ERRORS:
            # __str__() must return str or TypeError is raised.
            # Incorrect encoding names raise LookupError.
            # Invalid byte sequences can raise UnicodeDecodeError under the default
            # errors="strict" policy.
            # Repeated string concatenation in a loop can be inefficient; collect
            # pieces and use "".join(pieces) for predictable linear assembly.
        # COMPLEXITY:
            # str(existing_str) is commonly O(1) because strings are immutable.
            # Converting or decoding n characters/bytes is generally O(n) time and
            # O(n) result space.
            # Indexing is O(1) by code-point position in normal implementations;
            # slicing k characters requires O(k) time and space.

    str_empty_example = str()
    str_integer_example = str(2026)
    str_bytes_repr_example = str(b"hello")
    str_bytes_decode_example = str(b"hello", "utf-8")
    str_join_example = " ".join(["Python", "built-ins", "notes"])

    # sum(iterable, start=0)
        # PURPOSE:
            # Adds items from left to right, beginning with start.
        # REQUIREMENTS:
            # Items and start must support compatible addition.
            # It is primarily designed for numeric summation.
        # RETURN VALUE:
            # The accumulated result.
        # EMPTY INPUT:
            # sum([]) returns start, which is 0 by default.
        # BOOLEAN VALUES:
            # bool is a subclass of int, so True contributes 1 and False 0.
            # sum(boolean_conditions) is a common way to count true conditions.
        # STRINGS:
            # sum() rejects strings. Use "".join(strings), which is clearer and
            # asymptotically more efficient.
        # LISTS / TUPLES:
            # Supplying [] or () as start can technically concatenate compatible
            # sequences, but repeated concatenation can be O(n²). Use list
            # comprehensions, extend(), or itertools.chain() instead.
        # FLOATING-POINT ACCURACY:
            # Floating-point addition is not exact or fully associative.
            # Modern Python versions improved sum() accuracy for floats and complex
            # values, but math.fsum() is the specialized choice when high-accuracy
            # floating summation is important.
        # OTHER NUMERIC TYPES:
            # Decimal, Fraction, complex, and custom addable types can work when
            # start and item types are compatible.
        # EDGE CASES:
            # Mixed incompatible values raise TypeError at the failing addition.
            # NaN normally propagates through floating summation.
            # Very large integers are exact but their operations become more
            # expensive as the number of bits grows.
        # COMPLEXITY:
            # O(n) additions.
            # Auxiliary state is O(1), excluding the size of the growing numeric
            # result and implementation-specific compensated summation state.

    sum_numbers_example = sum([10, 20, 30])
    sum_start_example = sum([1, 2, 3], 10)
    sum_empty_example = sum([])
    sum_boolean_count_example = sum(
        [number > 0 for number in [-2, 0, 4, 8]]
    )
    sum_complex_example = sum([1 + 2j, 3 + 4j], 0j)

    # super()
    # super(type, object_or_type)
        # PURPOSE:
            # Returns a proxy that performs attribute lookup after a specified
            # class in the method resolution order.
        # IMPORTANT CONCEPT:
            # super() does not simply mean "call my parent."
            # It means "continue lookup after this class in this object's MRO."
            # This distinction enables cooperative multiple inheritance.
        # ZERO-ARGUMENT FORM:
            # Commonly used inside a method defined with normal def syntax.
            # Python obtains the current class and first method argument from the
            # compiler-created __class__ context.
            # Example: super().__init__()
        # TWO-ARGUMENT FORM:
            # super(CurrentClass, instance) searches after CurrentClass in the
            # instance's MRO.
            # super(CurrentClass, Subclass) can be used for class-level lookup.
        # COOPERATIVE INHERITANCE:
            # Methods in a multiple-inheritance chain should generally use
            # compatible signatures and call super() so each class in the MRO has
            # an opportunity to participate exactly once.
        # DESCRIPTOR BEHAVIOR:
            # The proxy performs attribute lookup and binds descriptors according
            # to the target object or class.
        # EDGE CASES / ERRORS:
            # Zero-argument super() outside a suitable method raises RuntimeError.
            # Nested functions and generator expressions can make zero-argument
            # super() confusing because their first argument/context differs.
            # Supplying a type and unrelated object raises TypeError.
            # Hard-coding ParentClass.method(self) can skip MRO participants and is
            # usually less cooperative than super().
        # COMPLEXITY:
            # Creating the proxy is O(1).
            # Attribute lookup depends on MRO length and descriptor behavior.

    class PartTwoBaseGreeter:
        def greet(self):
            return "Hello"

    class PartTwoNamedGreeter(PartTwoBaseGreeter):
        def __init__(self, name):
            self.name = name

        def greet(self):
            base_message = super().greet()
            return f"{base_message}, {self.name}!"

    greeter_example = PartTwoNamedGreeter("Jonathan")
    super_zero_argument_example = greeter_example.greet()
    super_explicit_proxy = super(PartTwoNamedGreeter, greeter_example)
    super_explicit_example = super_explicit_proxy.greet()
    greeter_mro_example = PartTwoNamedGreeter.__mro__

    # tuple()
    # tuple(iterable)
        # PURPOSE:
            # Creates an immutable ordered sequence.
        # CONSTRUCTION:
            # tuple() creates an empty tuple.
            # tuple(iterable) consumes items in order.
            # Literal syntax commonly uses parentheses and commas.
        # SINGLE-ITEM EDGE CASE:
            # The comma creates a tuple, not the parentheses.
            # ("only") is a string; ("only",) is a one-item tuple.
        # IMMUTABILITY:
            # Tuple positions cannot be added, removed, or reassigned.
            # A tuple can still reference mutable objects whose contents change.
        # HASHABILITY:
            # A tuple is hashable only when every contained item is hashable.
            # Suitable tuples can be dictionary keys and set members.
        # COPY BEHAVIOR:
            # tuple(iterable) creates references to the same item objects; it is
            # shallow.
            # Passing an exact tuple may return the same tuple because no mutable
            # copy is required.
        # PACKING / UNPACKING:
            # coordinates = 10, 20 packs a tuple.
            # x, y = coordinates unpacks it.
            # The number of targets must match unless starred unpacking is used.
        # COMPARISON:
            # Tuples compare lexicographically when corresponding values are
            # orderable.
        # COMPLEXITY:
            # Construction from n items: O(n) time and O(n) space.
            # Indexing and len(): O(1).
            # Membership: O(n) worst case.
            # Slicing k items: O(k) time and space.
            # Concatenation creates a new tuple in O(n + m) time and space.

    empty_tuple_example = tuple()
    tuple_from_list_example = tuple(["red", "green", "blue"])
    tuple_single_item_example = ("only",)
    tuple_not_single_item_example = ("only")

    mutable_item = [1, 2]
    tuple_with_mutable_item = (mutable_item,)
    mutable_item.append(3)
    tuple_reflects_nested_mutation = tuple_with_mutable_item

    packed_tuple_example = 10, 20
    unpacked_x, unpacked_y = packed_tuple_example

    # type(object)
    # type(name, bases, namespace, **keywords)
        # ONE-ARGUMENT PURPOSE:
            # Returns the exact class/type of an object.
        # TYPE VS ISINSTANCE:
            # type(value) is SomeType requires an exact type match.
            # isinstance(value, SomeType) also accepts subclasses and is usually
            # preferred for polymorphic code.
        # THREE-ARGUMENT PURPOSE:
            # Dynamically creates a class.
            # name must be a string class name.
            # bases must be a tuple of base classes.
            # namespace must be a dictionary containing class attributes/methods.
            # It is broadly comparable to executing a class statement, but the
            # direct three-argument form does not call metaclass __prepare__().
            # types.new_class() is better when full dynamic class-statement
            # preparation behavior is required.
        # METACLASSES:
            # type is the default metaclass for most classes.
            # Classes are normally instances of type, while ordinary objects are
            # instances of their own classes.
            # A custom metaclass can customize class creation and behavior.
        # EDGE CASES:
            # type(obj) ignores isinstance-style virtual subclass relationships.
            # Dynamic class creation must provide compatible bases and namespace.
            # Metaclass conflicts or invalid base combinations raise TypeError.
            # The three-argument form is powerful but a normal class statement is
            # usually easier to read and gives better support for advanced class
            # body features.
        # COMPLEXITY:
            # type(object) is O(1).
            # Dynamic class creation depends on base classes, namespace size,
            # descriptors, __set_name__(), __init_subclass__(), and metaclass work.

    type_integer_example = type(42)
    type_exact_check_example = type(True) is int
    type_isinstance_comparison_example = isinstance(True, int)

    def dynamic_describe(self):
        return f"DynamicStudent(name={self.name!r})"

    DynamicStudent = type(
        "DynamicStudent",
        (object,),
        {
            "school": "UT Austin",
            "__init__": lambda self, name: setattr(self, "name", name),
            "describe": dynamic_describe
        }
    )

    dynamic_student_example = DynamicStudent("Jonathan")
    dynamic_type_name_example = type(dynamic_student_example).__name__
    dynamic_type_method_example = dynamic_student_example.describe()
    class_is_instance_of_type_example = isinstance(DynamicStudent, type)

    # vars()
    # vars(object)
        # NO-ARGUMENT PURPOSE:
            # Behaves like locals() in the current scope.
        # OBJECT FORM PURPOSE:
            # Returns the object's __dict__ attribute.
        # COMMON SUPPORTED OBJECTS:
            # Many modules, classes, functions, and ordinary class instances.
        # RETURN VALUE:
            # The actual __dict__ object, which may be a writable dict or a
            # read-only mappingproxy depending on the object.
        # INSTANCE BEHAVIOR:
            # vars(instance) often returns the writable dictionary storing dynamic
            # instance attributes. Mutating it can change the instance directly.
        # CLASS BEHAVIOR:
            # vars(SomeClass) returns the class namespace mappingproxy, which is
            # read-only through that view. Use setattr(SomeClass, name, value) to
            # modify class attributes normally.
        # EDGE CASES / ERRORS:
            # Objects without __dict__, including many built-ins and instances
            # using restrictive __slots__, cause TypeError.
            # The no-argument form follows the same optimized-scope caveats as
            # locals(); changing its returned mapping does not reliably change
            # actual local variables in a function.
            # Exposing vars(instance) can expose implementation details that a
            # stable public API may prefer to hide.
        # COMPLEXITY:
            # Object form is typically O(1) because it retrieves __dict__.
            # No-argument form may require O(k) snapshot work for k local names,
            # depending on scope and implementation.

    class PartTwoVarsExample:
        class_attribute = "shared"

        def __init__(self):
            self.instance_attribute = "individual"

    vars_instance = PartTwoVarsExample()
    vars_instance_example = vars(vars_instance)
    vars_instance_example["added_through_dict"] = True
    vars_mutation_changed_instance = vars_instance.added_through_dict
    vars_class_example = vars(PartTwoVarsExample)

    # zip(*iterables, strict=False)
        # PURPOSE:
            # Lazily combines corresponding items from multiple iterables into
            # tuples.
        # RETURN VALUE:
            # A zip iterator.
        # OUTPUT SHAPE:
            # zip(a, b) yields 2-tuples.
            # zip(a, b, c) yields 3-tuples.
            # zip(one_iterable) yields 1-tuples.
            # zip() with no iterables yields an empty iterator.
        # DEFAULT LENGTH BEHAVIOR:
            # Stops when the shortest iterable is exhausted.
            # Extra items in longer iterables are silently ignored.
        # STRICT MODE:
            # strict=True, added in Python 3.10, raises ValueError when iterable
            # lengths differ.
            # The mismatch may not be discovered until the iterator is consumed.
            # strict=True is useful when unequal lengths indicate a programming
            # error rather than intended truncation.
        # LAZY / CONSUMPTION BEHAVIOR:
            # Source iterators advance only as zip results are requested.
            # A zip object is normally single-use.
            # Python evaluates and advances input iterators from left to right.
        # COMMON USES:
            # Pairing names with scores.
            # Parallel iteration.
            # Creating a dictionary with dict(zip(keys, values, strict=True)).
            # Transposing rectangular rows using zip(*rows, strict=True).
            # Unzipping pairs using firsts, seconds = zip(*pairs).
        # EDGE CASES:
            # With default truncation, important data can be silently lost.
            # strict=True does not know all lengths in advance for arbitrary
            # iterators; errors can occur after earlier tuples were already yielded.
            # Infinite iterables are allowed when another iterable provides a
            # finite stopping point under default behavior.
        # COMPLEXITY:
            # Creation: O(k) setup for k iterables, normally small.
            # Producing n tuples of width k: O(nk) item retrieval and tuple output.
            # Iterator state: O(k).
            # list(zip(...)) additionally requires O(nk) output storage.

    zip_names = ["Ana", "Luis", "Mia"]
    zip_scores = [95, 88, 91]
    zip_iterator_example = zip(zip_names, zip_scores)
    zip_list_example = list(zip_iterator_example)
    zip_dictionary_example = dict(zip(zip_names, zip_scores, strict=True))

    zip_short_example = list(zip([1, 2, 3], ["a", "b"]))
    zip_one_iterable_example = list(zip([10, 20]))
    zip_zero_iterables_example = list(zip())

    matrix_rows = [
        (1, 2, 3),
        (4, 5, 6)
    ]
    transposed_matrix_example = list(zip(*matrix_rows, strict=True))

    paired_values = [("A", 1), ("B", 2), ("C", 3)]
    unzipped_letters, unzipped_numbers = zip(*paired_values, strict=True)

    # __import__(name, globals=None, locals=None, fromlist=(), level=0)
        # PURPOSE:
            # Low-level function used by Python's import statement machinery.
        # NORMAL RECOMMENDATION:
            # Use an import statement for normal fixed imports.
            # Use importlib.import_module() for most dynamic imports.
            # Direct __import__() calls are uncommon and easier to misuse.
        # NAME:
            # A string naming the module or package.
        # GLOBALS / LOCALS:
            # These mappings help determine package context for relative imports.
            # The locals argument is retained for interface compatibility but is
            # not generally central to ordinary import resolution.
        # FROMLIST:
            # An empty fromlist commonly causes __import__("package.module") to
            # return the top-level package.
            # A non-empty fromlist requests the named module/package object that
            # contains the requested attributes.
        # LEVEL:
            # 0 means absolute import.
            # Positive values request relative import levels and require an
            # appropriate package context.
        # RETURN VALUE:
            # A module object, but exactly which module is returned depends on
            # name and fromlist.
        # CACHING:
            # Imported modules are normally cached in sys.modules.
            # Repeated imports usually return the cached module rather than fully
            # re-executing its top-level code.
        # SIDE EFFECTS:
            # Importing can execute arbitrary top-level module code.
            # Modules may modify global state, register plugins, open resources,
            # or raise exceptions while importing.
        # SECURITY:
            # Do not import arbitrary user-controlled module names in a privileged
            # process. Importing is code execution, not passive data loading.
            # Restrict dynamic imports to an allowlist when input is untrusted.
        # EDGE CASES / ERRORS:
            # ModuleNotFoundError when the requested module cannot be found.
            # ImportError for other import failures, including missing from-import
            # names in some contexts.
            # Exceptions raised by module top-level code propagate.
            # Circular imports can expose partially initialized modules.
        # COMPLEXITY:
            # Cached lookup can be close to O(1) dictionary access plus attribute
            # handling.
            # First import cost depends on finder/loader work, file I/O, parsing,
            # compilation, dependency imports, and executed module code.

    imported_math_module = __import__("math")
    import_sqrt_example = imported_math_module.sqrt(81)

